import XCTest

@testable import Schrift

/// Byte-exact regression tests for the Yjs update encoder. The expected bytes
/// are golden fixtures generated by the real `yjs` library (`Y.encodeStateAsUpdate`
/// over `blocksToYDoc(blocks, "document-store")`) with clientID 0xDEADBEEF, so a
/// pass means the Swift encoder is wire-compatible with yjs itself.
final class YjsEncoderTests: XCTestCase {
    private let clientID: UInt32 = 0xDEAD_BEEF

    private func U(_ n: Int) -> String { String(format: "%04x", n) + "0000-0000-4000-8000-000000000000" }
    private var P: [(key: String, value: YAnyValue)] {
        [
            ("backgroundColor", .string("default")), ("textColor", .string("default")),
            ("textAlignment", .string("left")),
        ]
    }
    private func para(_ runs: [InlineRun], _ id: Int) -> BlockNoteBlock {
        BlockNoteBlock(node: "paragraph", props: P, runs: runs, id: U(id))
    }
    private func assertGolden(
        _ blocks: [BlockNoteBlock], _ expected: String, _ message: String = "", file: StaticString = #filePath,
        line: UInt = #line
    ) {
        XCTAssertEqual(
            BlockNoteYjs.encode(blocks, clientID: clientID).hexString, expected, message, file: file, line: line)
    }

    func testEmptyParagraph() {
        assertGolden(
            [para([], 1)],
            ""
        )
    }

    func testParagraph() {
        assertGolden(
            [para([InlineRun("Just a paragraph.")], 1)],
            ""
        )
    }

    func testHeadingLevel2() {
        let block = BlockNoteBlock(
            node: "heading", props: P + [("level", .int(2)), ("isToggleable", .bool(false))],
            runs: [InlineRun("Heading two")], id: U(1))
        assertGolden(
            [block],
            ""
        )
    }

    func testBoldRun() {
        assertGolden(
            [para([InlineRun("Hello "), InlineRun("world", marks: [("bold", "{}")])], 1)],
            ""
        )
    }

    func testMultipleInlineMarks() {
        let runs = [
            InlineRun("Some "), InlineRun("italic", marks: [("italic", "{}")]), InlineRun(" and "),
            InlineRun("bold", marks: [("bold", "{}")]), InlineRun(" and "), InlineRun("code", marks: [("code", "{}")]),
            InlineRun(" here."),
        ]
        assertGolden(
            [para(runs, 1)],
            ""
        )
    }

    func testBulletList() {
        let blocks = [
            BlockNoteBlock(node: "bulletListItem", props: P, runs: [InlineRun("one")], id: U(1)),
            BlockNoteBlock(node: "bulletListItem", props: P, runs: [InlineRun("two")], id: U(2)),
        ]
        assertGolden(
            blocks,
            ""
        )
    }

    func testNumberedListHasStartProp() {
        let blocks = [
            BlockNoteBlock(
                node: "numberedListItem", props: P + [("start", .null)], runs: [InlineRun("first")], id: U(1)),
            BlockNoteBlock(
                node: "numberedListItem", props: P + [("start", .null)], runs: [InlineRun("second")], id: U(2)),
        ]
        assertGolden(
            blocks,
            ""
        )
    }

    func testCheckListHasCheckedProp() {
        let blocks = [
            BlockNoteBlock(
                node: "checkListItem", props: P + [("checked", .bool(false))], runs: [InlineRun("todo")], id: U(1)),
            BlockNoteBlock(
                node: "checkListItem", props: P + [("checked", .bool(true))], runs: [InlineRun("done")], id: U(2)),
        ]
        assertGolden(
            blocks,
            ""
        )
    }

    func testQuoteHasNoAlignment() {
        let block = BlockNoteBlock(
            node: "quote", props: [("backgroundColor", .string("default")), ("textColor", .string("default"))],
            runs: [InlineRun("quoted")], id: U(1))
        assertGolden(
            [block],
            ""
        )
    }

    func testCodeBlockHasLanguage() {
        let block = BlockNoteBlock(
            node: "codeBlock", props: [("language", .string("swift"))], runs: [InlineRun("let x = 1")], id: U(1))
        assertGolden(
            [block],
            ""
        )
    }

    func testDividerHasNoTextChild() {
        let blocks = [
            para([InlineRun("above")], 1),
            BlockNoteBlock(node: "divider", props: [], runs: [], id: U(2)),
            para([InlineRun("below")], 3),
        ]
        assertGolden(
            blocks,
            ""
        )
    }

    func testLinkMark() {
        let runs = [
            InlineRun("See "), InlineRun("docs", marks: [("link", "{\"href\":\"https://example.com\"}")]),
            InlineRun(" now"),
        ]
        assertGolden(
            [para(runs, 1)],
            ""
        )
    }

    func testStrikeLeadingMark() {
        let runs = [InlineRun("gone", marks: [("strike", "{}")]), InlineRun(" text")]
        assertGolden(
            [para(runs, 1)],
            ""
        )
    }

    func testUnicodeUsesUtf16LengthAndUtf8Bytes() {
        assertGolden(
            [para([InlineRun("café 😀 end")], 1)],
            ""
        )
    }

    /// An image is a leaf (no `xmlText` child) that still carries props. Golden
    /// bytes captured like every fixture here: real yjs `Y.encodeStateAsUpdate`
    /// over `blocksToYDoc(blocks, "document-store")`, @blocknote/core 0.51.4 (the
    /// version the docs frontend pins), clientID 0xDEADBEEF. Prop order matches
    /// the 0.51.4 image propSchema. `previewWidth` is emitted as `undefined`
    /// (0x7f), NOT omitted — confirmed empirically against the real library; the
    /// image block has no `textColor`.
    func testImageBlockIsLeafWithProps() {
        let block = BlockNoteBlock(
            node: "image",
            props: [
                ("textAlignment", .string("left")),
                ("backgroundColor", .string("default")),
                ("name", .string("photo.jpg")),
                (
                    "url",
                    .string(
                        "https://docs.example.test/media/11111111-1111-4111-8111-111111111111/attachments/22222222-2222-4222-8222-222222222222.jpg"
                    )
                ),
                ("caption", .string("")),
                ("showPreview", .bool(true)),
                ("previewWidth", .undefined),
            ],
            runs: [], id: U(1))
        assertGolden(
            [block],
            ""
        )
    }

    /// A generic file attachment is BlockNote's stock `file` block: a leaf, like
    /// the image, but with a **different and shorter** prop set — four props,
    /// with no `textAlignment`, no `textColor`, no `showPreview` and no
    /// `previewWidth`. Anyone tempted to copy the image's prop list should read
    /// these bytes instead.
    ///
    /// Captured the same way as every fixture here: real yjs 13.6.31 over
    /// `@blocknote/server-util@0.51.4`'s `blocksToYXmlFragment(blocks, fragment)`
    /// into a `Y.Doc` whose clientID was pinned to 0xDEADBEEF before any content
    /// existed, then `Y.encodeStateAsUpdate`. The harness was validated by
    /// reproducing `testImageBlockIsLeafWithProps` byte for byte first.
    ///
    /// Note the struct count: `0108` — eight structs against the image's eleven,
    /// which is the three missing props.
    func testFileBlockIsLeafWithProps() {
        let block = BlockNoteBlock(
            node: "file",
            props: [
                ("backgroundColor", .string("default")),
                ("name", .string("Q3 report.pdf")),
                (
                    "url",
                    .string(
                        "https://docs.example.test/media/11111111-1111-4111-8111-111111111111/attachments/22222222-2222-4222-8222-222222222222.pdf"
                    )
                ),
                ("caption", .string("")),
            ],
            runs: [], id: U(1))
        assertGolden(
            [block],
            ""
        )
    }

    /// A nested list: each block's children live in a second `blockGroup` inside
    /// its container, emitted after the content element's props and before the
    /// container's `id`, with the content element as its left origin. Covers two
    /// levels, a sibling after a nested group at both depths, and mixed kinds.
    ///
    /// Generated by `blocksToYXmlFragment` (BlockNote 0.51.4) into a `Y.Doc` with
    /// clientID 0xDEADBEEF. The numbered item's `start` was then set from
    /// undefined (`7f`) to null (`7e`), the value the encoder writes and that
    /// `testNumberedListHasStartProp` pins — the one byte that differs.
    func testNestedListChildrenGoInANestedBlockGroup() {
        let checklist = BlockNoteBlock(
            node: "checkListItem", props: P + [("checked", .bool(false))], runs: [InlineRun("C")], id: U(3))
        var b = BlockNoteBlock(node: "bulletListItem", props: P, runs: [InlineRun("B")], id: U(2))
        b.children = [checklist]
        let n = BlockNoteBlock(
            node: "numberedListItem", props: P + [("start", .null)], runs: [InlineRun("N")], id: U(4))
        var a = BlockNoteBlock(node: "bulletListItem", props: P, runs: [InlineRun("A")], id: U(1))
        a.children = [b, n]
        let d = BlockNoteBlock(node: "bulletListItem", props: P, runs: [InlineRun("D")], id: U(5))
        assertGolden(
            [a, d],
            ""
        )
    }

    /// A photo and a file nested under a checklist item: leaf children in the
    /// item's nested `blockGroup`, exactly like nested list items — the image and
    /// `file` nodes keep their own prop sets and stay childless — followed by a
    /// sibling item back at the top level.
    ///
    /// Captured like `testFileBlockIsLeafWithProps`, with yjs 13.6.33 (a patch
    /// release on the same v1 update format as 13.6.31): real
    /// `@blocknote/server-util@0.51.4` `blocksToYXmlFragment(blocks, fragment)`
    /// into a `Y.Doc` whose clientID was pinned to 0xDEADBEEF before any content
    /// existed, then `Y.encodeStateAsUpdate`. No byte was edited by hand. The props
    /// are the ones `MarkdownYjs` emits, in its order, which BlockNote's prop
    /// schemas produce too.
    func testListItemLeafChildrenGoInANestedBlockGroup() {
        let media = "https://docs.example.test/media/11111111-1111-4111-8111-111111111111/attachments/"
        let image = BlockNoteBlock(
            node: "image",
            props: [
                ("textAlignment", .string("left")),
                ("backgroundColor", .string("default")),
                ("name", .string("photo.jpg")),
                ("url", .string(media + "22222222-2222-4222-8222-222222222222.jpg")),
                ("caption", .string("")),
                ("showPreview", .bool(true)),
                ("previewWidth", .undefined),
            ],
            runs: [], id: U(2))
        let file = BlockNoteBlock(
            node: "file",
            props: [
                ("backgroundColor", .string("default")),
                ("name", .string("report.pdf")),
                ("url", .string(media + "33333333-3333-4333-8333-333333333333.pdf")),
                ("caption", .string("")),
            ],
            runs: [], id: U(3))
        var task = BlockNoteBlock(
            node: "checkListItem", props: P + [("checked", .bool(false))], runs: [InlineRun("Task")], id: U(1))
        task.children = [image, file]
        let next = BlockNoteBlock(
            node: "checkListItem", props: P + [("checked", .bool(false))], runs: [InlineRun("Next")], id: U(4))
        assertGolden(
            [task, next],
            ""
        )
    }
}
